91	    public static void uploadToBookeeper(Namespace dlogNamespace,
92	                                         InputStream uploadedInputStream,
93	                                         String destPkgPath)
94	            throws IOException {
95	
96	        // if the dest directory does not exist, create it.
97	        if (dlogNamespace.logExists(destPkgPath)) {
98	            // if the destination file exists, write a log message
99	            log.info(String.format("Target function file already exists at '%s'. Overwriting it now",
100	                    destPkgPath));
101	            dlogNamespace.deleteLog(destPkgPath);
102	        }
103	        // copy the topology package to target working directory
104	        log.info(String.format("Uploading function package to '%s'",
105	                destPkgPath));
106	
107	        try (DistributedLogManager dlm = dlogNamespace.openLog(destPkgPath)) {
108	            try (AppendOnlyStreamWriter writer = dlm.getAppendOnlyStreamWriter()){
109	
110	                try (OutputStream out = new DLOutputStream(dlm, writer)) {
111	                    int read = 0;
112	                    byte[] bytes = new byte[1024];
113	                    while ((read = uploadedInputStream.read(bytes)) != -1) {
114	                        out.write(bytes, 0, read);
115	                    }
116	                    out.flush();
117	                }
118	            }
119	        }
120	    }
